fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Helper to compute S(k) = sum_{i=1}^k a[i], where
    // a[i] = -i if i is odd, and +i if i is even.
    // We extend it so that for k <= 0 it returns 0.
    #[inline]
    fn prefix_sum(k: i8) -> i32 {
        let k_i = k as i32;
        if k_i <= 0 {
            0
        } else if k_i % 2 == 0 {
            // even k: S(k) = k/2
            k_i / 2
        } else {
            // odd k: S(k) = -(k+1)/2
            -(k_i + 1) / 2
        }
    }

    let mut result = Vec::with_capacity(queries.len());
    for (l, r) in queries {
        // We want sum_{i=l}^r a[i] = S(r) - S(l-1)
        let sum_r = prefix_sum(r);
        let sum_lm1 = prefix_sum(l - 1);
        let ans = sum_r - sum_lm1;
        result.push(ans as i8);
    }
    result
}

